Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='lawsat20000', at=datetime(2026, 11, 25, 0, 0, 0), actor='assistant', title='Before a law over runs of acts is extended with a new act, it runs at 20,000 cases on master', body='Before a law over runs of acts, orders of events or two replicas that diverge and join is extended with a new act, run it once at 20,000 cases on master and note the result. Then extend the law and run it again at 20,000 cases. Leave the count that is committed in the tree at what the suite can afford.', rationale='A law over sequences can pass thousands of cases and still fail on an order that it rarely draws. If the first 20,000-case run happens after the new act exists, an old failure is blamed on the new act. A run on master first shows which failures were already there.', supersedes=()))